    "materialDescription": "золотая пыль, стоящая как минимум 25 зм, расходуемая заклинанием",
    "duration": "Пока не рассеется",
    "concentration": false,
    "ritual": false,
    "description": "Вы касаетесь закрытой двери, окна, ворот, сундука или другого входа, и он становится запертым. Вы и указанные при накладывании этого заклинания существа можете открывать предмет как обычно. Вы можете также установить пароль, произношение которого в пределах 5 футов от предмета подавляет заклинание на 1 минуту. В противном случае предмет не открывается, пока его не сломают, или пока заклинание не рассеют или не подавят. Накладывание открывания на предмет подавляет волшебный замок на 10 минут.\nНаходящийся под действием этого заклинания предмет гораздо сложнее взломать и открыть силой; Сл выламывания и взлома замков увеличивается на 10.",
