    "range": "На себя",
    "components": "В, С, М (особые палочки, костяшки или фигурки с отметинами, стоящие как минимум 25 зм)",
    "componentFlags": {
      "verbal": true,
      "somatic": true,
      "material": true
    },
    "materialDescription": "особые палочки, костяшки или фигурки с отметинами, стоящие как минимум 25 зм",
    "duration": "Мгновенная",
    "concentration": false,
    "ritual": true,
    "description": "Подбрасывая инкрустированные камнями палочки, драконьи кости, раскладывая карты или используя другие инструменты для ворожбы, вы получаете знамение от иномировой сущности о результатах особого действия, которое вы планируете совершить в течение следующих 30 минут. Мастер выбирает одно из следующих возможных знамений:\n• Благо, для хороших результатов\n• Горе, для плохих результатов\n• Благо и горе, для результатов, одновременно хороших и плохих\n• Ничто, для результатов, которые и не хорошие и не плохие\nЗаклинание не принимает в расчёт обстоятельства, способные изменить исход, такие как накладывание дополнительных заклинаний или потерю или обретение спутников.\nЕсли вы накладываете это заклинание несколько раз до завершения продолжительного отдыха, существует накопительный шанс 25 процентов за каждое использование, начиная со второго, что вы получите случайный ответ. Мастер совершает этот бросок скрытно.",
