    "materialDescription": "агат, стоящий как минимум 1 000 зм, расходуемый заклинанием",
    "duration": "Мгновенная",
    "concentration": false,
    "ritual": false,
    "description": "Потратив время на прокладывание магических каналов в драгоценном камне, вы касаетесь им зверя или растения с размером не больше Огромного. У цели либо не должно быть значения Интеллекта, либо Интеллект должен быть не больше 3. Цель получает Интеллект 10. Цель также получает способность говорить на одном известном вам языке. Если цель — растение, оно получает возможность шевелить ветками, корнями, лианами, и так далее, и получает чувства, подобные человеческим. Мастер подбирает параметры для пробуждённого растения, будь то куст или дерево.\nПробуждённый зверь или растение очарован вами 30 дней, либо пока вы или ваши спутники не причините ему вред. Когда очарование спадает, пробуждённое существо решает, останется ли оно к вам дружелюбно, в зависимости от того, как вы с ним обращались.",
