    "description": "Вы призываете небожителя с показателем опасности 4 или меньше, появляющегося в свободном месте, которое вы видите в пределах дистанции. Небожитель исчезает, когда его хиты опускаются до 0, или когда заклинание оканчивается.\nНебожитель дружественен к вам и вашим спутникам, пока заклинание активно. Совершите проверку инициативы за небожителя, и он будет совершать свои собственные ходы. Он подчиняется отданным вами устно командам (действие не требуется), если они не противоречат его мировоззрению. Если вы не отдаёте команду, он защищается от враждебных существ, но действий не совершает.\nПараметры небожителя есть у Мастера.",
    "atHigherLevels": "Если вы накладываете это заклинание, используя ячейку 9 уровня, вы призываете небожителя с показателем опасности 5 или ниже.",
    "source": "PHB",
