    "duration": "Концентрация, вплоть до 1 часа",
    "concentration": true,
    "ritual": false,
    "description": "Вы вызываете прислуживающего элементаля. Выберите область воды, воздуха, земли или огня, помещающуюся в куб с длиной ребра 10 футов. В свободном пространство в пределах 10 клеток от выбранной области появляется соответствующий местности элементаль с показателем опасности 5 или меньше. Например, из костра выходит огненный элементаль, а земляной элементаль выбирается из-под земли. Элементаль исчезает, когда его хиты опускаются до 0, или когда заклинание оканчивается.\nЭлементаль дружественен к вам и вашим спутникам, пока заклинание активно. Совершите проверку инициативы за элементаля, и он будет совершать свои собственные ходы. Он подчиняется отданным вами устно командам (действие не требуется). Если вы не отдаёте команду, он защищается от враждебных существ, но действий не совершает.\nЕсли ваша концентрация нарушена, элементаль не исчезает. Вместо этого вы теряете над ним контроль, и он становится враждебным к вам и вашим спутникам, и может напасть. Неуправляемый элементаль не может быть отпущен вами, но он исчезает через 1 час после того, как был призван.\nПараметры элементаля есть у Мастера.",
    "atHigherLevels": "Если вы накладываете это заклинание, используя ячейку 6 уровня или выше, показатель опасности увеличивается на 1 за каждый уровень ячейки выше пятого.",
