    "name": "КОНТРЗАКЛИНАНИЕ",
    "level": 3,
    "school": "Ограждение",
    "time": "1 реакция, совершаемая вами, когда вы видите, как существо в пределах 60 футов от вас накладывает заклинание",
    "range": "60 футов",
