    "materialDescription": "",
    "duration": "Мгновенная",
    "concentration": false,
    "ritual": false,
    "description": "Вы пытаетесь прервать процесс накладывания заклинания. Если существо накладывает заклинание 3 уровня или ниже, его заклинание проваливается, и не оказывает никакого эффекта. Если оно накладывало заклинание 4 уровня или выше, совершите проверку базовой характеристики. Сл равна 10 + уровень заклинания. В случае успеха заклинание проваливается и не оказывает никакого эффекта.",
    "atHigherLevels": "Если вы накладываете это заклинание, используя ячейку 4 уровня или выше, прерванное заклинание автоматически не оказывает эффекта, если его уровень не превышает уровень использованной вами ячейки.",
