    "description": "Вы касаетесь существа и даруете ему некоторую защиту от смерти.\nКогда хиты цели впервые опускаются до 0 изза получения урона, хиты цели опускаются всего лишь до 1, и заклинание заканчивается.\nЕсли заклинание ещё действует, а цель попадает под действие эффекта, убивающего её мгновенно, не причиняя урона, то этот эффект игнорируется, и заклинание заканчивается.",
