    "materialDescription": "лист тиса",
    "duration": "Концентрация, вплоть до 10 минут",
    "concentration": true,
    "ritual": true,
    "description": "Пока заклинание активно, вы можете ощущать присутствие и местонахождение ядов, ядовитых существ и болезней в пределах 30 футов от себя. Вы также распознаёте вид яда, ядовитого существа или болезни.\nЗаклинание проницает большую часть барьеров, но блокируется 1 футом камня, 1 дюймом обычного металла, тонким листом свинца или 3 футами дерева или земли.",
    "atHigherLevels": "",
