    "description": "Вы посылаете негативную энергию в видимое вами существо в пределах дистанции, вызывая у него сильную боль. Цель должна совершить спасбросок Телосложения. В случае провала она получает урон некротической энергией 7к8 + 30, или половину этого урона в случае успеха. Гуманоид, убитый этим заклинанием, воскресает в начале вашего следующего хода как зомби, постоянно находящийся под вашим командованием и выполняющий ваши устные команды.",
