    "duration": "8 часов",
    "concentration": false,
    "ritual": false,
    "description": "Вы касаетесь согласного существа, даруя ограниченную способность предвидеть будущее. Пока заклинание активно, цель нельзя застать врасплох, и она совершает с преимуществом броски атаки, проверки характеристик и спасброски. Кроме того, пока заклинание активно, другие существа совершают по цели броски атаки с помехой.\nЭто заклинание мгновенно оканчивается, если вы активируете его ещё раз до окончания длительности.",
