    "description": "Вы открываете врата в межзвёздную тьму, область, населённую неизвестными кошмарами. Появляется сфера тьмы и холода с радиусом 20 футов, с центром на точке в пределах дистанции, существующая, пока активно заклинание. Эта пустота заполнена какофонией тихих шёпотов и хлюпающих шумов, которые слышно в пределах 30 футов. Никакой свет, ни магический, ни обычный, не может осветить эту местность, и существа, полностью находящиеся в этой области, ослеплены.\nПустота создаёт искажения в ткани пространства, и её местность является труднопроходимой. Все существа, начинающие ход в этой местности, получают урон холодом 2к6. Все существа, оканчивающие ход в этой местности, должны преуспеть в спасброске Ловкости, иначе получают урон кислотой 2к6, так как к ним прикасаются бледные потусторонние щупальца.",
