    "duration": "Мгновенная",
    "concentration": false,
    "ritual": false,
    "description": "На землю в цилиндре с радиусом 20 футов и высотой 40 футов, с центром на точке в пределах дистанции, падают куски льда. Все существа в цилиндре должны совершить спасбросок Ловкости. Существо получает дробящий урон 2к8 и урон холодом 4к6 при провале, или половину этого урона при успехе.\nГрад превращает область воздействия в труднопроходимую местность до конца вашего следующего хода.",
    "atHigherLevels": "Если вы накладываете это заклинание, используя ячейку 5 уровня или выше, дробящий урон увеличивается на 1к8 за каждый уровень ячейки выше четвёртого.",
