    "duration": "Мгновенная",
    "concentration": false,
    "ritual": false,
    "description": "Выберите предмет, видимый в пределах дистанции. Это может быть дверь, ящик, сундук, кандалы, навесной замок, или другой предмет, содержащий обычное или магическое средство, предотвращающее доступ.\nЦель, запертая обычным замком, заклинившая или запертая на засов, становится незапертой, незаклинившей, а засовы сами открываются. Если на предмете было несколько замков, открывается только один из них.\nЕсли вы выбрали цель, запертую волшебным замком, это заклинание подавляется на 10 минут, во время которых цель может открываться и закрываться как обычно.\nКогда вы накладываете это заклинание, от цели исходит громкий стук, слышимый с расстояния в 300 футов.",
