    "duration": "Мгновенная",
    "concentration": false,
    "ritual": false,
    "description": "Разряд молнии формирует линию длиной 100 футов и шириной 5 футов, вылетающую в выбранном вами направлении. Все существа в линии должны совершить спасбросок Ловкости. При провале существо получает урон электричеством 8к6, или половину урона при успехе.\nМолния поджигает горючие предметы в поражаемой области, которые никто не несёт и не носит.",
    "atHigherLevels": "Если вы накладываете это заклинание, используя ячейку 4 уровня или выше, урон увеличивается на 1к6 за каждый уровень ячейки выше третьего.",
