    "duration": "Мгновенная",
    "concentration": false,
    "ritual": false,
    "description": "Это заклинание чинит одно повреждение или разрыв на предмете, которого касаетесь, например, разорванное звено цепи, две половинки сломанного ключа, порванный плащ или протекающий бурдюк. Если повреждение или разрыв не больше 1 фута в длину, вы чините его, не оставляя следов.\nЭто заклинание может физически починить магический предмет или конструкта, но не может восстановить магию в таких предметах.",
