    "components": "В, С, М (кусочек медной проволоки)",
    "componentFlags": {
      "verbal": true,
      "somatic": true,
      "material": true
    },
    "materialDescription": "кусочек медной проволоки",
    "duration": "1 раунд",
    "concentration": false,
    "ritual": false,
    "description": "Вы указываете пальцем на существо, находящееся в пределах дистанции, и шепчете послание. Цель (и только цель) слышит его, и может ответить шёпотом, который услышите только вы.\nВы можете использовать это заклинание сквозь твёрдые препятствия, если вы знакомы с целью и знаете, что она находится за барьером. Магическая тишина, 1 фут камня, 1 дюйм обычного металла, тонкий лист свинца или 3 фута дерева блокируют заклинание. Заклинание не обязано идти по прямой линии, и может огибать углы и проходить через отверстия.",
    "atHigherLevels": "",
