    "description": "Луч тошнотворно-зелёной энергии устремляется к существу, находящемуся в пределах дистанции. Совершите дальнобойную атаку заклинанием по цели. При попадании цель получает урон ядом 2к8 и должна совершить спасбросок Телосложения.\nПри провале она становится также отравленной до конца вашего следующего хода.",
    "atHigherLevels": "Если вы накладываете это заклинание, используя ячейку 2 уровня или выше, урон увеличивается на 1к8 за каждый уровень ячейки выше первого.",
