    "materialDescription": "маленькое серебряное зеркало",
    "duration": "1 минута",
    "concentration": false,
    "ritual": false,
    "description": "Вы защищаете одно существо в пределах дистанции от атаки. Пока заклинание активно, все существа, нацеливающиеся на защищённое существо атаками или вредоносными заклинаниями, должны вначале совершить спасбросок Мудрости. При провале существо должно выбрать новую цель или потеряет атаку или заклинание. Это заклинание не защищает от эффектов, действующих на площадь, таких как взрыв огненного шара.\nЕсли защищённое существо совершает атаку, накладывает заклинание, оказывающее действие на враждебное существо или наносит урон другому существу, это заклинание оканчивается.",
    "atHigherLevels": "",
