    "components": "В, С, М (смесь порошков из бриллианта, изумруда, рубина и сапфира, стоящая как минимум 5 000 зм, расходуемая заклинанием)",
    "componentFlags": {
      "verbal": true,
      "somatic": true,
      "material": true
    },
    "materialDescription": "смесь порошков из бриллианта, изумруда, рубина и сапфира, стоящая как минимум 5 000 зм, расходуемая заклинанием",
    "duration": "Пока не рассеется",
    "concentration": false,
    "ritual": false,
    "description": "При помощи этого заклинания согласное существо или предмет можно защитить на время действия заклинания от обнаружения. Когда вы накладываете это заклинание и касаетесь цели, она становится невидимой, и не может стать целью заклинаний школы Прорицания, а также не обнаруживается сенсорами, созданными заклинаниями школы Прорицания.\nЕсли цель — существо, оно входит в состояние приостановленной жизнедеятельности. Время для него не течёт, и оно не стареет.\nВы можете определить условия, при которых заклинание окончится. Это может быть что угодно, но оно должно произойти в пределах 1 мили от цели. Примерами могут стать «через 1000 лет» и «когда проснётся тараск». Это заклинание также оканчивается, если цель получает урон.",
