    "duration": "Концентрация, вплоть до 10 минут Пол в пределах 20-футового радиуса с центром на точке в пределах дистанции покрывается шипами и колючками. Эта местность становится труднопроходимой на время действия заклинания. Когда существо перемещением входит в эту область или идёт по ней, оно получает колющий урон 2к4 за каждые 5 пройдённых футов.",
    "concentration": true,
    "ritual": false,
    "description": "Трансформация поверхности проходит практически незаметно, и шипы хорошо замаскированы. Существа, которые не видели эту местность в момент накладывания заклинания, должны совершить проверку Мудрости (Внимательность) против Сл ваших заклинаний, чтобы распознать местность опасной, перед тем как в неё войти.",
