    "materialDescription": "немного святой воды и бриллианты, стоящие как минимум 25 000 зм, расходуемые заклинанием",
    "duration": "Мгновенная",
    "concentration": false,
    "ritual": false,
    "description": "Вы касаетесь существа, мёртвого не больше двух сотен лет, умершего от чего угодно кроме старости. Если душа цели свободна и согласна, цель возвращается к жизни с полными хитами.\nЭто заклинание закрывает все раны, нейтрализует все яды, исцеляет все болезни и снимает все проклятья, бывшие у существа в момент смерти. Заклинание заменяет повреждённые и отсутствующие органы и части тела.\nЭто заклинание может даже воссоздать новое тело, если старого больше нет. В этом случае вы должны произнести вслух имя существа. Это существо появляется в свободном пространстве, выбранном вами в пределах 10 футов.",
