    "materialDescription": "Острый перец",
    "duration": "Концентрация, вплоть до 1 минуты",
    "concentration": true,
    "ritual": false,
    "description": "Вы касаетесь одного согласного существа и наделяете его силой изрыгать магическую энергию изо рта, при условии, что у существа есть рот. Выберите кислоту, холод, огонь, молнию или яд. Пока заклинание не закончится, существо может использовать действие, чтобы выдыхать энергию выбранного типа в 15-футовом конусе.\nКаждое существо в области должно совершить спасбросок Ловкости, и получить 3к6 урона выбранного типа при неудачном спасброске или вдвое меньший урон при удачном.",
    "atHigherLevels": "Если вы сотворяете это заклинание, используя ячейку заклинания 3 уровня или выше, урон увеличивается на 1к6 за каждый уровень ячейки выше 2.",
    "source": "XGE",
