    "concentration": true,
    "ritual": false,
    "description": "Выберите одно существо, видимое в пределах дистанции заклинания, а затем выберите один из следующих видов урона: звук, кислота, огонь, холодили электричество. Цель должна преуспеть в спасброске Телосложения, иначе будет подвержена эффекту заклинания в течение времени его действия. Когда цель впервые за ход получает урон выбранного вида, она также получает дополнительно 2к6 урона этого вида. Кроме того, цель теряет любые сопротивления к этому виду урона, пока не закончится заклинание.",
    "atHigherLevels": "Если вы сотворяете это заклинание, используя ячейку 5 уровня или выше, вы можете выбрать одну дополнительную цель за каждый уровень ячейки выше 5. Цели должны находиться в пределах 30 футов друг от друга, когда вы сотворяете заклинание.",
