    "duration": "мгновенная",
    "concentration": false,
    "ritual": false,
    "description": "Сильный холод окружает одно существо, которое вы можете видеть в пределах дистанции заклинания. Цель должна совершить спасбросок Телосложения. При провале цель получает урон холодом 1к6 и следующий бросок атаки оружием до конца своего следующего хода совершает с помехой.\nУрон заклинания увеличивается на 1к6, когда вы достигаете 5 уровня (2к6), 11 уровня (3к6) и 17 уровня (4к6).",
