    "duration": "мгновенная",
    "concentration": false,
    "ritual": false,
    "description": "Вы жертвуете своим здоровьем, чтобы излечить травмы другого существа. Вы получаете 4к8 некротического урона, который никак нельзя уменьшить, и одно существо по вашему выбору, которое вы видите в пределах дистанции, восстанавливает хиты в количестве, равном удвоенному полученному вами урону.",
    "atHigherLevels": "Если вы сотворяете это заклинание, используя ячейку заклинания 4 уровня или выше, урон увеличивается на 1к8 для каждого уровня ячейки выше 3.",
