    "ritual": false,
    "description": "Вы направляете первобытную магию, затачивающую ваши зубы или ногти, и готовитесь к агрессивной атаке. Совершите рукопашную атаку заклинанием против одного существа в пределах 5 футов от вас. При попадании цель получает урон кислотой 1к10. После того, как вы совершите атаку, ваши зубы или ногти вернутся в нормальное состояние.\nУрон заклинания увеличивается на 1к10, когда вы достигаете 5 уровня (2к10), 11 уровня (3к10) и 17 уровня (4к10).",
