    "description": "Вы получаете сопротивление к урону звуком, кислотой, огнём, холодом и электричеством на время действия заклинания.\nКогда вы получаете урон одного из этих видов, вы можете реакцией получить иммунитет к этому виду урона, включая тот урон, который спровоцировал эту реакцию. В этом случае вы теряете сопротивление к остальным видам урона, а иммунитет пропадает в конце вашего следующего хода, после чего заклинание заканчивается.",
