    "materialDescription": "",
    "duration": "мгновенная",
    "concentration": false,
    "ritual": false,
    "description": "Вы высвобождаете силу своей мысли, чтобы выжечь разум до десяти существ по вашему выбору, которых вы можете видеть в пределах дистанции. Существа, у которых Интеллект равен 2 или ниже, не попадают под действие этого заклинания.\nКаждая цель должна совершить спасбросок Интеллекта. При провале цель получает 14к6 психического урона и становится ошеломлённой. При успехе цель получает только половину урона и не ошеломлена. Если этот урон убивает цель, её голова взрывается, при наличии таковой.\nОшеломлённая цель может совершать спасбросок Интеллекта в конце каждого своего хода. При успехе ошеломление спадает.",
