    "ritual": false,
    "description": "Вы вызываете оглушительный раскат грома, который слышен на расстоянии до 100 футов. Все существа кроме вас в пределах 5 футов должны совершить спасбросок Телосложения. При провале существо получает урон звуком 1к6.\nУрон заклинания увеличивается на 1к6, когда вы достигаете 5 уровня (2к6), 11 уровня (3к6) и 17 уровня (4к6).",
