    "description": "Вы произносите божественное слово и извергаете из себя обжигающее сияние. Каждое существо по вашему выбору, которое вы можете видеть в пределах дистанции, должно преуспеть в спасброске Телосложения или получит урон излучением 1к6.\nУрон заклинания увеличивается на 1к6, когда вы достигаете 5 уровня (2к6), 11 уровня (3к6), и 17 уровня (4к6).",
