    "ritual": false,
    "description": "Вы движетесь подобно ветру. Пока действует заклинание, ваше движение не вызывает провоцированных атак.\nЕдиножды до окончания действия заклинания вы можете получить преимущество к одной атаке оружием в свой ход. Эта атака наносит дополнительные 1к8 урона силовым полем при попадании. Вне зависимости от того, попали вы или промахнулись, ваша пешая скорость передвижения увеличивается на 30 футов до конца этого хода.",
